INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b28', 'beginner', 'Git', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'リポジトリ整理', '作業用の枝、切ってもらえますか？', 'こちらで用意します。名前が決まれば教えてください。バグには少し席を外してもらいます。', 'こちらでよういします。なまえがきまればおしえてください。ばぐにはすこしせきをはずしてもらいます。', '[{"text":"こちらで用意します。","kana":"こちらでよういします。"},{"text":"名前が決まれば教えてください。","kana":"なまえがきまればおしえてください。"},{"text":"バグには少し席を外してもらいます。","kana":"ばぐにはすこしせきをはずしてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b29', 'beginner', '障害', 'WebApp部', '中村 / PM', '/assets/avatars/nakamura.svg', 'トップ表示', 'トップが白い画面のままです。今見てもらえますか？', '先にログを確認します。原因が分かり次第ご連絡します。コミット前にもう一度見ます。', 'さきにろぐをかくにんします。げんいんがわかりしだいごれんらくします。こみっとまえにもういちどみます。', '[{"text":"先にログを確認します。","kana":"さきにろぐをかくにんします。"},{"text":"原因が分かり次第ご連絡します。","kana":"げんいんがわかりしだいごれんらくします。"},{"text":"コミット前にもう一度見ます。","kana":"こみっとまえにもういちどみます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b30', 'beginner', 'cache', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', '商品画像', '画像を変えたのに、前のまま見えます。', 'キャッシュの可能性があります。一度切り分けます。まずは落ち着いてデバッグします。', 'きゃっしゅのかのうせいがあります。いちどきりわけます。まずはおちついてでばっぐします。', '[{"text":"キャッシュの可能性があります。","kana":"きゃっしゅのかのうせいがあります。"},{"text":"一度切り分けます。","kana":"いちどきりわけます。"},{"text":"まずは落ち着いてデバッグします。","kana":"まずはおちついてでばっぐします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b31', 'beginner', '権限', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', '編集画面', 'スタッフにも編集できるようにできますか？', '権限を広げます。対象の方を教えてください。スコープは広げすぎないようにします。', 'けんげんをひろげます。たいしょうのかたをおしえてください。すこーぷはひろげすぎないようにします。', '[{"text":"権限を広げます。","kana":"けんげんをひろげます。"},{"text":"対象の方を教えてください。","kana":"たいしょうのかたをおしえてください。"},{"text":"スコープは広げすぎないようにします。","kana":"すこーぷはひろげすぎないようにします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b32', 'beginner', 'CSV', 'Orion inc.', '鈴木 / 事業部', '/assets/avatars/suzuki.svg', '顧客一覧', '一覧を CSV で出せますか？', 'CSV で出せます。項目を確認してから作ります。フィードバックを反映します。', 'CSV でだせます。こうもくをかくにんしてからつくります。ふぃーどばっくをはんえいします。', '[{"text":"CSV で出せます。","kana":"CSV でだせます。"},{"text":"項目を確認してから作ります。","kana":"こうもくをかくにんしてからつくります。"},{"text":"フィードバックを反映します。","kana":"ふぃーどばっくをはんえいします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m01', 'intermediate', 'PR', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '管理画面改修', 'PR #128 の修正内容を確認してもらえますか？', '確認します。API 周りを中心にレビューします。問題なければ本日中に反映します。ステータスはグリーンに戻します。', 'かくにんします。API まわりをちゅうしんにれびゅーします。もんだいなければほんじつちゅうにはんえいします。すてーたすはぐりーんにもどします。', '[{"text":"確認します。","kana":"かくにんします。"},{"text":"API 周りを中心にレビューします。","kana":"API まわりをちゅうしんにれびゅーします。"},{"text":"問題なければ本日中に反映します。","kana":"もんだいなければほんじつちゅうにはんえいします。"},{"text":"ステータスはグリーンに戻します。","kana":"すてーたすはぐりーんにもどします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m02', 'intermediate', 'Issue', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'EC サイト UI 改修', '商品詳細の購入ボタンがスマホだと下にずれています。Issue #42 に書きました。', 'Issue #42 を見ます。スマホ表示を中心に原因を調べて、本日中にご連絡します。アサインされた瞬間から勝ち筋です。', 'Issue #42 をみます。すまほひょうじをちゅうしんにげんいんをしらべて、ほんじつちゅうにごれんらくします。あさいんされたしゅんかんからかちすじです。', '[{"text":"Issue #42 を見ます。","kana":"Issue #42 をみます。"},{"text":"スマホ表示を中心に原因を調べて、本日中にご連絡します。","kana":"すまほひょうじをちゅうしんにげんいんをしらべて、ほんじつちゅうにごれんらくします。"},{"text":"アサインされた瞬間から勝ち筋です。","kana":"あさいんされたしゅんかんからかちすじです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m03', 'intermediate', 'API', '合同会社 Lumio', '高橋 / 広報', '/assets/avatars/takahashi.svg', 'お知らせ API', '一覧が空になることがあります。API 側でしょうか？', '先に API のレスポンスを確認します。500 が出ていれば共有します。レビューは軽く流して大丈夫な温度です。', 'さきに API のれすぽんすをかくにんします。500 がでていればきょうゆうします。れびゅーはかるくながしてだいじょうぶなおんどです。', '[{"text":"先に API のレスポンスを確認します。","kana":"さきに API のれすぽんすをかくにんします。"},{"text":"500 が出ていれば共有します。","kana":"500 がでていればきょうゆうします。"},{"text":"レビューは軽く流して大丈夫な温度です。","kana":"れびゅーはかるくながしてだいじょうぶなおんどです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m04', 'intermediate', 'DB', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '顧客管理', '検索が遅いです。DB のインデックス、見てもらえますか？', 'DB のクエリを見ます。必要ならインデックスを足して、結果を共有します。ここはサクッとクローズしておきます。', 'DB のくえりをみます。ひつようならいんでっくすをたして、けっかをきょうゆうします。ここはさくっとくろーずしておきます。', '[{"text":"DB のクエリを見ます。","kana":"DB のくえりをみます。"},{"text":"必要ならインデックスを足して、結果を共有します。","kana":"ひつようならいんでっくすをたして、けっかをきょうゆうします。"},{"text":"ここはサクッとクローズしておきます。","kana":"ここはさくっとくろーずしておきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m05', 'intermediate', '見積もり', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', 'フォーム改善', '送信後に完了メッセージを出せますか？見積もりだけ先にください。', '対応できます。半日ほどで入れられます。文言があれば先に共有ください。スコープ調整はこちらの得意領域です。', 'たいおうできます。はんにちほどでいれられます。もんごんがあればさきにきょうゆうください。すこーぷちょうせいはこちらのとくいりょういきです。', '[{"text":"対応できます。","kana":"たいおうできます。"},{"text":"半日ほどで入れられます。","kana":"はんにちほどでいれられます。"},{"text":"文言があれば先に共有ください。","kana":"もんごんがあればさきにきょうゆうください。"},{"text":"スコープ調整はこちらの得意領域です。","kana":"すこーぷちょうせいはこちらのとくいりょういきです。"}]');
