INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m15', 'intermediate', 'review', 'WebApp部', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'デザイン実装', '実装とデザインの差分、レビューしてもらえますか？', '差分を見てコメントします。大きいずれがあれば先に直します。リスクは先に潰してから共有します。', 'さぶんをみてこめんとします。おおきいずれがあればさきになおします。りすくはさきにつぶしてからきょうゆうします。', '[{"text":"差分を見てコメントします。","kana":"さぶんをみてこめんとします。"},{"text":"大きいずれがあれば先に直します。","kana":"おおきいずれがあればさきになおします。"},{"text":"リスクは先に潰してから共有します。","kana":"りすくはさきにつぶしてからきょうゆうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m16', 'intermediate', 'test', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', 'ログイン改修', 'テスト項目、最低限どれを見ればよいですか？', 'ログイン成功と失敗、パスワード再設定の3つを先に見てください。残りは明日回します。デプロイまでセットで片します。', 'ろぐいんせいこうとしっぱい、ぱすわーどさいせっていの3つをさきにみてください。のこりはあしたまわします。でぷろいまでせっとでかたします。', '[{"text":"ログイン成功と失敗、パスワード再設定の3つを先に見てください。","kana":"ろぐいんせいこうとしっぱい、ぱすわーどさいせっていの3つをさきにみてください。"},{"text":"残りは明日回します。","kana":"のこりはあしたまわします。"},{"text":"デプロイまでセットで片します。","kana":"でぷろいまでせっとでかたします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m17', 'intermediate', 'SQL', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'レポート出力', '月次レポートの集計が合わない、と営業から連絡です。', 'SQL の集計条件を一度切り分けます。ずれている月があれば教えてください。コミットメッセージも今日は冴えています。', 'SQL のしゅうけいじょうけんをいちどきりわけます。ずれているつきがあればおしえてください。こみっとめっせーじもきょうはさえています。', '[{"text":"SQL の集計条件を一度切り分けます。","kana":"SQL のしゅうけいじょうけんをいちどきりわけます。"},{"text":"ずれている月があれば教えてください。","kana":"ずれているつきがあればおしえてください。"},{"text":"コミットメッセージも今日は冴えています。","kana":"こみっとめっせーじもきょうはさえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m18', 'intermediate', 'アクセス解析', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', 'GA設定', 'コンバージョンが 0 のままです。設定ミスでしょうか？', '計測タグを先に確認します。イベント名が違っていれば直して共有します。ログが素直ならこちらの勝ちです。', 'けいそくたぐをさきにかくにんします。いべんとめいがちがっていればなおしてきょうゆうします。ろぐがすなおならこちらのかちです。', '[{"text":"計測タグを先に確認します。","kana":"けいそくたぐをさきにかくにんします。"},{"text":"イベント名が違っていれば直して共有します。","kana":"いべんとめいがちがっていればなおしてきょうゆうします。"},{"text":"ログが素直ならこちらの勝ちです。","kana":"ろぐがすなおならこちらのかちです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m19', 'intermediate', 'レスポンシブ', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', '商品一覧', 'タブレットだとカードが2列になって崩れる、と報告がありました。', 'いったんこちらで再現してみます。直したらステージングに上げます。キャッチアップ済みなので先に進めます。', 'いったんこちらでさいげんしてみます。なおしたらすてーじんぐにあげます。きゃっちあっぷずみなのでさきにすすめます。', '[{"text":"いったんこちらで再現してみます。","kana":"いったんこちらでさいげんしてみます。"},{"text":"直したらステージングに上げます。","kana":"なおしたらすてーじんぐにあげます。"},{"text":"キャッチアップ済みなので先に進めます。","kana":"きゃっちあっぷずみなのでさきにすすめます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m20', 'intermediate', 'Issue', 'WebApp部', '中村 / PM', '/assets/avatars/nakamura.svg', '検索改善', '検索の件、Issue #57 にまとめました。優先度は中です。', 'Issue #57 を見ます。こちらは別Issueに分けた方がよさそうな点があれば書きます。アサインされた瞬間から勝ち筋です。', 'Issue #57 をみます。こちらはべつIssueにわけたほうがよさそうなてんがあればかきます。あさいんされたしゅんかんからかちすじです。', '[{"text":"Issue #57 を見ます。","kana":"Issue #57 をみます。"},{"text":"こちらは別Issueに分けた方がよさそうな点があれば書きます。","kana":"こちらはべつIssueにわけたほうがよさそうなてんがあればかきます。"},{"text":"アサインされた瞬間から勝ち筋です。","kana":"あさいんされたしゅんかんからかちすじです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m21', 'intermediate', '納期', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', 'LP改修', '来週水曜の社内発表に間に合わせたいです。どこまで切れますか？', '見出しと導線までは間に合わせます。アニメーションは次の週に回します。レビューは軽く流して大丈夫な温度です。', 'みだしとどうせんまではまにあわせます。あにめーしょんはつぎのしゅうにまわします。れびゅーはかるくながしてだいじょうぶなおんどです。', '[{"text":"見出しと導線までは間に合わせます。","kana":"みだしとどうせんまではまにあわせます。"},{"text":"アニメーションは次の週に回します。","kana":"あにめーしょんはつぎのしゅうにまわします。"},{"text":"レビューは軽く流して大丈夫な温度です。","kana":"れびゅーはかるくながしてだいじょうぶなおんどです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m22', 'intermediate', '追加料金', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', 'フォーム項目追加', '項目を3つ足したいです。追加料金の目安を先にください。', '3項目なら半日です。この部分だけ追加対応になります。見積もりを今日出します。ここはサクッとクローズしておきます。', '3こうもくならはんにちです。このぶぶんだけついかたいおうになります。みつもりをきょうだします。ここはさくっとくろーずしておきます。', '[{"text":"3項目なら半日です。","kana":"3こうもくならはんにちです。"},{"text":"この部分だけ追加対応になります。","kana":"このぶぶんだけついかたいおうになります。"},{"text":"見積もりを今日出します。","kana":"みつもりをきょうだします。"},{"text":"ここはサクッとクローズしておきます。","kana":"ここはさくっとくろーずしておきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m23', 'intermediate', '打合せ', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', '週次同期', '木曜 10 時、進捗の短い打合せできますか？', '木曜 10 時で大丈夫です。その前に進捗メモを送ります。スコープ調整はこちらの得意領域です。', 'もくよう 10 じでだいじょうぶです。そのまえにしんちょくめもをおくります。すこーぷちょうせいはこちらのとくいりょういきです。', '[{"text":"木曜 ","kana":"もくよう "},{"text":"10 時で大丈夫です。","kana":"10 じでだいじょうぶです。"},{"text":"その前に進捗メモを送ります。","kana":"そのまえにしんちょくめもをおくります。"},{"text":"スコープ調整はこちらの得意領域です。","kana":"すこーぷちょうせいはこちらのとくいりょういきです。"}]');
