INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m35', 'intermediate', '仕様変更', 'WebApp部', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'カードUI', 'ホバーで拡大はやめて、影だけにしてほしいです。', '影だけに変えます。この部分は追加対応にはなりません。コミットメッセージも今日は冴えています。', 'かげだけにかえます。このぶぶんはついかたいおうにはなりません。こみっとめっせーじもきょうはさえています。', '[{"text":"影だけに変えます。","kana":"かげだけにかえます。"},{"text":"この部分は追加対応にはなりません。","kana":"このぶぶんはついかたいおうにはなりません。"},{"text":"コミットメッセージも今日は冴えています。","kana":"こみっとめっせーじもきょうはさえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m36', 'intermediate', '500', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '画像アップロード', '大きい画像を上げると 500 になります。Issue #88 です。', 'Issue #88 を見ます。サイズ上限を入れて、失敗時の文言も足します。ログが素直ならこちらの勝ちです。', 'Issue #88 をみます。さいずじょうげんをいれて、しっぱいじのもんごんもたします。ろぐがすなおならこちらのかちです。', '[{"text":"Issue #88 を見ます。","kana":"Issue #88 をみます。"},{"text":"サイズ上限を入れて、失敗時の文言も足します。","kana":"さいずじょうげんをいれて、しっぱいじのもんごんもたします。"},{"text":"ログが素直ならこちらの勝ちです。","kana":"ろぐがすなおならこちらのかちです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m37', 'intermediate', 'CSV', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', '勤怠取込', 'CSV 取込で1行目がヘッダー扱いされないことがあります。', '1行目の判定を直します。サンプルファイルを1つください。キャッチアップ済みなので先に進めます。', '1ぎょうめのはんていをなおします。さんぷるふぁいるを1つください。きゃっちあっぷずみなのでさきにすすめます。', '[{"text":"1行目の判定を直します。","kana":"1ぎょうめのはんていをなおします。"},{"text":"サンプルファイルを1つください。","kana":"さんぷるふぁいるを1つください。"},{"text":"キャッチアップ済みなので先に進めます。","kana":"きゃっちあっぷずみなのでさきにすすめます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m38', 'intermediate', '顧客説明', '山田商店', '山田 / 店主', '/assets/avatars/yamada.svg', '在庫同期', '在庫の反映に時間がかかる理由を、短く教えてください。', 'まとめて更新しているため、数分ずれることがあります。即時には変えられます。このくらいならコーヒーが冷める前に終わります。', 'まとめてこうしんしているため、すうふんずれることがあります。そくじにはかえられます。このくらいならこーひーがさめるまえにおわります。', '[{"text":"まとめて更新しているため、数分ずれることがあります。","kana":"まとめてこうしんしているため、すうふんずれることがあります。"},{"text":"即時には変えられます。","kana":"そくじにはかえられます。"},{"text":"このくらいならコーヒーが冷める前に終わります。","kana":"このくらいならこーひーがさめるまえにおわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m39', 'intermediate', 'LP', '森カフェ', '森 / 店主', '/assets/avatars/mori.svg', 'ランチ告知', 'ランチの写真、もう少し明るくできますか？今週の掲示に使いたいです。', '明るくした版を今日中に試せそうです。気に入らなければ元に戻します。リカバリ手順はもう頭にあります。', 'あかるくしたばんをきょうじゅうにためせそうです。きにいらなければもとにもどします。りかばりてじゅんはもうあたまにあります。', '[{"text":"明るくした版を今日中に試せそうです。","kana":"あかるくしたばんをきょうじゅうにためせそうです。"},{"text":"気に入らなければ元に戻します。","kana":"きにいらなければもとにもどします。"},{"text":"リカバリ手順はもう頭にあります。","kana":"りかばりてじゅんはもうあたまにあります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m40', 'intermediate', 'SEO', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', 'メタ整備', 'メタディスクリプションが空のページがあります。一覧はシートの B 列です。', 'B 列のページから埋めます。長いものは 80 字を目安に切ります。ここはサクッとクローズしておきます。', 'B れつのぺーじからうめます。ながいものは 80 じをめやすにきります。ここはさくっとくろーずしておきます。', '[{"text":"B 列のページから埋めます。","kana":"B れつのぺーじからうめます。"},{"text":"長いものは","kana":"ながいものは"},{"text":" 80 字を目安に切ります。","kana":" 80 じをめやすにきります。"},{"text":"ここはサクッとクローズしておきます。","kana":"ここはさくっとくろーずしておきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a01', 'advanced', '緊急', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '管理画面 500', '本番の管理画面が 500 です。今すぐ見てもらえますか？金曜夕方ですみません。', '今から見ます。500 のログと API を先に当たります。切り分けでき次第、復旧手順を共有します。アサインが重いほど燃えます。', 'いまからみます。500 のろぐと API をさきにあたります。きりわけできしだい、ふっきゅうてじゅんをきょうゆうします。あさいんがおもいほどもえます。', '[{"text":"今から見ます。","kana":"いまからみます。"},{"text":"500 のログと API を先に当たります。","kana":"500 のろぐと API をさきにあたります。"},{"text":"切り分けでき次第、復旧手順を共有します。","kana":"きりわけできしだい、ふっきゅうてじゅんをきょうゆうします。"},{"text":"アサインが重いほど燃えます。","kana":"あさいんがおもいほどもえます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a02', 'advanced', 'PR', '合同会社 Lumio', '高橋 / 広報', '/assets/avatars/takahashi.svg', 'お知らせ API', 'PR #128 と Issue #42、どちらを先にマージしますか？リリースは今夜です。', 'Issue #42 を先に main へ入れます。PR #128 はレビュー後、v1.2 に間に合わせます。リカバリはお茶の子です。', 'Issue #42 をさきに main へいれます。PR #128 はれびゅーご、v1.2 にまにあわせます。りかばりはおちゃのこです。', '[{"text":"Issue #42 を先に","kana":"Issue #42 をさきに"},{"text":" main へ入れます。","kana":" main へいれます。"},{"text":"PR #128 はレビュー後、v1.2 に間に合わせます。","kana":"PR #128 はれびゅーご、v1.2 にまにあわせます。"},{"text":"リカバリはお茶の子です。","kana":"りかばりはおちゃのこです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a03', 'advanced', 'DB', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', '注文検索', '管理画面の検索がタイムアウトします。お客様対応が止まっています。', 'DB の遅いクエリを特定します。一時的に条件を絞る案内を出して、インデックス追加後に再デプロイします。スコープが増えてもこちらのペースは変わりません。', 'DB のおそいくえりをとくていします。いちじてきにじょうけんをしぼるあんないをだして、いんでっくすついかごにさいでぷろいします。すこーぷがふえてもこちらのぺーすはかわりません。', '[{"text":"DB の遅いクエリを特定します。","kana":"DB のおそいくえりをとくていします。"},{"text":"一時的に条件を絞る案内を出して、インデックス追加後に再デプロイします。","kana":"いちじてきにじょうけんをしぼるあんないをだして、いんでっくすついかごにさいでぷろいします。"},{"text":"スコープが増えてもこちらのペースは変わりません。","kana":"すこーぷがふえてもこちらのぺーすはかわりません。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a04', 'advanced', '権限', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', '権限まわり', '一般ユーザーに CSV 出力を出してよいか、先方に確認中です。実装は進めますか？', 'UI は進めます。CSV 出力はフラグで閉じておき、許可が出てから API を開きます。障害にもこちらのスケジュールに合わせてもらいます。', 'UI はすすめます。CSV しゅつりょくはふらぐでとじておき、きょかがでてから API をひらきます。しょうがいにもこちらのすけじゅーるにあわせてもらいます。', '[{"text":"UI は進めます。","kana":"UI はすすめます。"},{"text":"CSV 出力はフラグで閉じておき、許可が出てから","kana":"CSV しゅつりょくはふらぐでとじておき、きょかがでてから"},{"text":" API を開きます。","kana":" API をひらきます。"},{"text":"障害にもこちらのスケジュールに合わせてもらいます。","kana":"しょうがいにもこちらのすけじゅーるにあわせてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a05', 'advanced', '顧客説明', '山田商店', '山田 / 店主', '/assets/avatars/yamada.svg', '在庫表示', '在庫がずれる理由を、あまり技術用語なしでお客様に説明したいです。', '表示が遅れるのは、更新が数分まとめて入るためです。今から即時反映に変えて、完了後にご連絡します。フルスタックなので切り分けは一筆です。', 'ひょうじがおくれるのは、こうしんがすうふんまとめてはいるためです。いまからそくじはんえいにかえて、かんりょうごにごれんらくします。ふるすたっくなのできりわけはいっぴつです。', '[{"text":"表示が遅れるのは、更新が数分まとめて入るためです。","kana":"ひょうじがおくれるのは、こうしんがすうふんまとめてはいるためです。"},{"text":"今から即時反映に変えて、完了後にご連絡します。","kana":"いまからそくじはんえいにかえて、かんりょうごにごれんらくします。"},{"text":"フルスタックなので切り分けは一筆です。","kana":"ふるすたっくなのできりわけはいっぴつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a06', 'advanced', 'release', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '夜間リリース', 'main に戻したあと、develop の TODO は残してよいですか？', 'main へ戻した差分だけ今夜出します。develop の TODO は Issue #42 に移して、明日続けます。コミット一つで空気が変わります。', 'main へもどしたさぶんだけこんやだします。develop の TODO は Issue #42 にうつして、あしたつづけます。こみっとひとつでくうきがかわります。', '[{"text":"main へ戻した差分だけ今夜出します。","kana":"main へもどしたさぶんだけこんやだします。"},{"text":"develop の TODO は Issue #42 に移して、明日続けます。","kana":"develop の TODO は Issue #42 にうつして、あしたつづけます。"},{"text":"コミット一つで空気が変わります。","kana":"こみっとひとつでくうきがかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a07', 'advanced', 'webhook', '合同会社 Lumio', '高橋 / 広報', '/assets/avatars/takahashi.svg', 'Webhook', '外部連携が時々落ちます。リトライしてくれますか？', 'API 側で最大3回リトライします。失敗が続く場合は 500 を見て、@tanaka にも共有します。デプロイ判断はこちらに任せてください。', 'API がわでさいだい3かいりとらいします。しっぱいがつづくばあいは 500 をみて、@tanaka にもきょうゆうします。でぷろいはんだんはこちらにまかせてください。', '[{"text":"API 側で最大3回リトライします。失敗が続く場合は","kana":"API がわでさいだい3かいりとらいします。しっぱいがつづくばあいは"},{"text":" 500 を見て、","kana":" 500 をみて、"},{"text":"@tanaka にも共有します。","kana":"@tanaka にもきょうゆうします。"},{"text":"デプロイ判断はこちらに任せてください。","kana":"でぷろいはんだんはこちらにまかせてください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a08', 'advanced', 'UI', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'スマホ購入導線', '購入ボタンがキーボードで隠れる、と再度連絡が来ました。今日中に仮対応できますか？', '今日中に仮対応します。ボタン位置を固定して、余白を足します。恒久対応は PR #128 にまとめます。本番の機嫌は今日は良さそうです。', 'きょうじゅうにかりたいおうします。ぼたんいちをこていして、よはくをたします。こうきゅうたいおうは PR #128 にまとめます。ほんばんのきげんはきょうはよさそうです。', '[{"text":"今日中に仮対応します。","kana":"きょうじゅうにかりたいおうします。"},{"text":"ボタン位置を固定して、余白を足します。","kana":"ぼたんいちをこていして、よはくをたします。"},{"text":"恒久対応は PR #128 にまとめます。","kana":"こうきゅうたいおうは PR #128 にまとめます。"},{"text":"本番の機嫌は今日は良さそうです。","kana":"ほんばんのきげんはきょうはよさそうです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a09', 'advanced', '障害', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', '本番500', '本番が断続的に 500 です。`/health` は 200 ですが、注文 API だけ落ちています。', '注文 API のログから切り分けます。`/health` が 200 ならアプリ自体は生きています。原因が分かり次第ご連絡します。ログを見る前からだいたい勝ち筋は見えています。', 'ちゅうもん API のろぐからきりわけます。`/health` が 200 ならあぷりじたいはいきています。げんいんがわかりしだいごれんらくします。ろぐをみるまえからだいたいかちすじはみえています。', '[{"text":"注文","kana":"ちゅうもん"},{"text":" API のログから切り分けます。","kana":" API のろぐからきりわけます。"},{"text":"`/health` が 200 ならアプリ自体は生きています。原因が分かり次第ご連絡します。","kana":"`/health` が 200 ならあぷりじたいはいきています。げんいんがわかりしだいごれんらくします。"},{"text":"ログを見る前からだいたい勝ち筋は見えています。","kana":"ろぐをみるまえからだいたいかちすじはみえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a10', 'advanced', 'release', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', 'v1.3リリース', 'v1.3、今夜 22:00 公開でよいですか？失敗時の戻し手順も欲しいです。', '22:00 公開で進めます。失敗したら v1.2 に戻します。手順はリリース前に共有します。アサインが重いほど燃えます。', '22:00 こうかいですすめます。しっぱいしたら v1.2 にもどします。てじゅんはりりーすまえにきょうゆうします。あさいんがおもいほどもえます。', '[{"text":"22:00 公開で進めます。","kana":"22:00 こうかいですすめます。"},{"text":"失敗したら v1.2 に戻します。","kana":"しっぱいしたら v1.2 にもどします。"},{"text":"手順はリリース前に共有します。","kana":"てじゅんはりりーすまえにきょうゆうします。"},{"text":"アサインが重いほど燃えます。","kana":"あさいんがおもいほどもえます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a11', 'advanced', '緊急', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '認証障害', 'ログインできない、と問い合わせが連続しています。金曜 18 時ですみません。', '今から認証ログを見ます。セッション切れか、IdP 側かを先に切り分けます。復旧でき次第ご連絡します。リカバリはお茶の子です。', 'いまからにんしょうろぐをみます。せっしょんぎれか、IdP がわかをさきにきりわけます。ふっきゅうできしだいごれんらくします。りかばりはおちゃのこです。', '[{"text":"今から認証ログを見ます。","kana":"いまからにんしょうろぐをみます。"},{"text":"セッション切れか、IdP 側かを先に切り分けます。","kana":"せっしょんぎれか、IdP がわかをさきにきりわけます。"},{"text":"復旧でき次第ご連絡します。","kana":"ふっきゅうできしだいごれんらくします。"},{"text":"リカバリはお茶の子です。","kana":"りかばりはおちゃのこです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a12', 'advanced', 'webhook', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', '決済webhook', '決済 webhook が 2 重に来て、注文が二重登録されています。', '同じ ID は 1 回だけ処理するよう直します。重複分は手動で取り消して一覧を送ります。スコープが増えてもこちらのペースは変わりません。', 'おなじ ID は 1 かいだけしょりするようなおします。ちょうふくぶんはしゅどうでとりけしていちらんをおくります。すこーぷがふえてもこちらのぺーすはかわりません。', '[{"text":"同じ ID は 1 回だけ処理するよう直します。","kana":"おなじ ID は 1 かいだけしょりするようなおします。"},{"text":"重複分は手動で取り消して一覧を送ります。","kana":"ちょうふくぶんはしゅどうでとりけしていちらんをおくります。"},{"text":"スコープが増えてもこちらのペースは変わりません。","kana":"すこーぷがふえてもこちらのぺーすはかわりません。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a13', 'advanced', 'staging', 'WebApp部', '中村 / PM', '/assets/avatars/nakamura.svg', '権限リリース', 'ステージングは通ったので、本番へ出してよいですか？ロール変更ありです。', '念のためバックアップを取ってから作業します。ロール変更後に管理者ログインだけ先に確認します。障害にもこちらのスケジュールに合わせてもらいます。', 'ねんのためばっくあっぷをとってからさぎょうします。ろーるへんこうごにかんりしゃろぐいんだけさきにかくにんします。しょうがいにもこちらのすけじゅーるにあわせてもらいます。', '[{"text":"念のためバックアップを取ってから作業します。","kana":"ねんのためばっくあっぷをとってからさぎょうします。"},{"text":"ロール変更後に管理者ログインだけ先に確認します。","kana":"ろーるへんこうごにかんりしゃろぐいんだけさきにかくにんします。"},{"text":"障害にもこちらのスケジュールに合わせてもらいます。","kana":"しょうがいにもこちらのすけじゅーるにあわせてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a14', 'advanced', 'production', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'キャッシュ障害', '本番だけ古い CSS が出ています。ステージングは新しいです。お客様から指摘が来ました。', '本番のキャッシュを切ります。ステージングが新しいなら成果物自体は問題なさそうです。反映後にスクショを送ります。フルスタックなので切り分けは一筆です。', 'ほんばんのきゃっしゅをきります。すてーじんぐがあたらしいならせいかぶつじたいはもんだいなさそうです。はんえいごにすくしょをおくります。ふるすたっくなのできりわけはいっぴつです。', '[{"text":"本番のキャッシュを切ります。","kana":"ほんばんのきゃっしゅをきります。"},{"text":"ステージングが新しいなら成果物自体は問題なさそうです。","kana":"すてーじんぐがあたらしいならせいかぶつじたいはもんだいなさそうです。"},{"text":"反映後にスクショを送ります。","kana":"はんえいごにすくしょをおくります。"},{"text":"フルスタックなので切り分けは一筆です。","kana":"ふるすたっくなのできりわけはいっぴつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a15', 'advanced', 'Git', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', 'ホットフィックス', 'hotfix を main に直接出してよいですか？develop はまだレビュー中です。', 'いったん main には入れずに、hotfix 枝から出します。あとで develop へ戻して PR を出します。コミット一つで空気が変わります。', 'いったん main にはいれずに、hotfix えだからだします。あとで develop へもどして PR をだします。こみっとひとつでくうきがかわります。', '[{"text":"いったん main には入れずに、hotfix 枝から出します。","kana":"いったん main にはいれずに、hotfix えだからだします。"},{"text":"あとで develop へ戻して PR を出します。","kana":"あとで develop へもどして PR をだします。"},{"text":"コミット一つで空気が変わります。","kana":"こみっとひとつでくうきがかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a16', 'advanced', 'PR', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'レビュー lag', 'PR #201 が 2 日止まっています。v1.2 に含めたいです。@tanaka にも見てもらえますか？', 'PR #201 を今日見ます。@tanaka にも依頼しておきます。指摘が少なければ午後までにマージします。デプロイ判断はこちらに任せてください。', 'PR #201 をきょうみます。@tanaka にもいらいしておきます。してきがすくなければごごまでにまーじします。でぷろいはんだんはこちらにまかせてください。', '[{"text":"PR #201 を今日見ます。","kana":"PR #201 をきょうみます。"},{"text":"@tanaka にも依頼しておきます。","kana":"@tanaka にもいらいしておきます。"},{"text":"指摘が少なければ午後までにマージします。","kana":"してきがすくなければごごまでにまーじします。"},{"text":"デプロイ判断はこちらに任せてください。","kana":"でぷろいはんだんはこちらにまかせてください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a17', 'advanced', 'SQL', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '集計ずれ', '売上集計が管理画面と CSV で違います。経営会議が明日 10 時です。', '集計 SQL と CSV の条件を突き合わせます。税込か税抜かの差が多いです。明日の午前中に共有します。本番の機嫌は今日は良さそうです。', 'しゅうけい SQL と CSV のじょうけんをつきあわせます。ぜいこみかぜいぬきかのさがおおいです。あしたのごぜんちゅうにきょうゆうします。ほんばんのきげんはきょうはよさそうです。', '[{"text":"集計","kana":"しゅうけい"},{"text":" SQL と CSV の条件を突き合わせます。","kana":" SQL と CSV のじょうけんをつきあわせます。"},{"text":"税込か税抜かの差が多いです。明日の午前中に共有します。","kana":"ぜいこみかぜいぬきかのさがおおいです。あしたのごぜんちゅうにきょうゆうします。"},{"text":"本番の機嫌は今日は良さそうです。","kana":"ほんばんのきげんはきょうはよさそうです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a18', 'advanced', '認証', 'WebApp部', '中村 / PM', '/assets/avatars/nakamura.svg', '権限昇格', '一般ユーザーが管理者画面を開けた、という報告があります。今すぐ見てください。', '権限チェックを先に見ます。開けていれば即閉じます。影響範囲はログから洗い出します。ログを見る前からだいたい勝ち筋は見えています。', 'けんげんちぇっくをさきにみます。あけていればそくとじます。えいきょうはんいはろぐからあらいだします。ろぐをみるまえからだいたいかちすじはみえています。', '[{"text":"権限チェックを先に見ます。","kana":"けんげんちぇっくをさきにみます。"},{"text":"開けていれば即閉じます。","kana":"あけていればそくとじます。"},{"text":"影響範囲はログから洗い出します。","kana":"えいきょうはんいはろぐからあらいだします。"},{"text":"ログを見る前からだいたい勝ち筋は見えています。","kana":"ろぐをみるまえからだいたいかちすじはみえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a19', 'advanced', '見積もり', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', '大規模追加', '会員ランクとクーポンを足したいです。工期と概算を先にください。仕様はまだ粗いです。', '先に見積もりを出します。仕様が粗いので、前提を箇条書きにして金額の幅も書きます。フィードバックより先に直しておきました。', 'さきにみつもりをだします。しようがあらいので、ぜんていをかじょうがきにしてきんがくのはばもかきます。ふぃーどばっくよりさきになおしておきました。', '[{"text":"先に見積もりを出します。","kana":"さきにみつもりをだします。"},{"text":"仕様が粗いので、前提を箇条書きにして金額の幅も書きます。","kana":"しようがあらいので、ぜんていをかじょうがきにしてきんがくのはばもかきます。"},{"text":"フィードバックより先に直しておきました。","kana":"ふぃーどばっくよりさきになおしておきました。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a20', 'advanced', 'デザイン', 'WebApp部', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'デザインシステム', 'ボタンをすべて `--brand` に寄せたいです。例外はエラーだけ残してください。', '通常ボタンは `--brand` に揃えます。エラーだけ赤を残します。差分は PR にスクショ付きで出します。リカバリはお茶の子です。', 'つうじょうぼたんは `--brand` にそろえます。えらーだけあかをのこします。さぶんは PR にすくしょつきでだします。りかばりはおちゃのこです。', '[{"text":"通常ボタンは `--brand` に揃えます。","kana":"つうじょうぼたんは `--brand` にそろえます。"},{"text":"エラーだけ赤を残します。","kana":"えらーだけあかをのこします。"},{"text":"差分は PR にスクショ付きで出します。","kana":"さぶんは PR にすくしょつきでだします。"},{"text":"リカバリはお茶の子です。","kana":"りかばりはおちゃのこです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a21', 'advanced', 'release', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', 'リリースノート', 'リリースノート、`## 変更点` と `- 修正` の形で明日までに欲しいです。', '`## 変更点` の形でまとめます。`- 修正` と `- 追加` に分けます。スコープが増えてもこちらのペースは変わりません。', '`## へんこうてん` のけいでまとめます。`- しゅうせい` と `- ついか` にわけます。すこーぷがふえてもこちらのぺーすはかわりません。', '[{"text":"`## 変更点` の形でまとめます。","kana":"`## へんこうてん` のけいでまとめます。"},{"text":"`- 修正` と","kana":"`- しゅうせい` と"},{"text":" `- 追加` に分けます。","kana":" `- ついか` にわけます。"},{"text":"スコープが増えてもこちらのペースは変わりません。","kana":"すこーぷがふえてもこちらのぺーすはかわりません。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a22', 'advanced', '障害', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', '在庫API', '在庫 API がタイムアウトして、カートが進めません。売上に直結しています。', '在庫 API のタイムアウトを先に見ます。一時的にキャッシュを長くして、復旧後に戻します。障害にもこちらのスケジュールに合わせてもらいます。', 'ざいこ API のたいむあうとをさきにみます。いちじてきにきゃっしゅをながくして、ふっきゅうごにもどします。しょうがいにもこちらのすけじゅーるにあわせてもらいます。', '[{"text":"在庫 API のタイムアウトを先に見ます。","kana":"ざいこ API のたいむあうとをさきにみます。"},{"text":"一時的にキャッシュを長くして、復旧後に戻します。","kana":"いちじてきにきゃっしゅをながくして、ふっきゅうごにもどします。"},{"text":"障害にもこちらのスケジュールに合わせてもらいます。","kana":"しょうがいにもこちらのすけじゅーるにあわせてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a23', 'advanced', 'deploy', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'デプロイ失敗', 'デプロイが途中で落ちました。本番は旧版のままです。再実行してよいですか？', '旧版のままなら再実行してよいです。失敗ログを見て、マイグレーションが途中でないことだけ確認します。フルスタックなので切り分けは一筆です。', 'きゅうばんのままならさいじっこうしてよいです。しっぱいろぐをみて、まいぐれーしょんがとちゅうでないことだけかくにんします。ふるすたっくなのできりわけはいっぴつです。', '[{"text":"旧版のままなら再実行してよいです。","kana":"きゅうばんのままならさいじっこうしてよいです。"},{"text":"失敗ログを見て、マイグレーションが途中でないことだけ確認します。","kana":"しっぱいろぐをみて、まいぐれーしょんがとちゅうでないことだけかくにんします。"},{"text":"フルスタックなので切り分けは一筆です。","kana":"ふるすたっくなのできりわけはいっぴつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a24', 'advanced', '顧客説明', '山田商店', '山田 / 店主', '/assets/avatars/yamada.svg', '予約トラブル', '予約が二重に入った理由を、店のスタッフにも分かる言葉でください。', '同じ操作を短時間に 2 回したため、二重に入りました。今は 1 回だけ通るよう直しています。コミット一つで空気が変わります。', 'おなじそうさをたんじかんに 2 かいしたため、にじゅうにはいりました。いまは 1 かいだけとおるようなおしています。こみっとひとつでくうきがかわります。', '[{"text":"同じ操作を短時間に 2 回したため、二重に入りました。","kana":"おなじそうさをたんじかんに 2 かいしたため、にじゅうにはいりました。"},{"text":"今は 1 回だけ通るよう直しています。","kana":"いまは 1 かいだけとおるようなおしています。"},{"text":"コミット一つで空気が変わります。","kana":"こみっとひとつでくうきがかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a25', 'advanced', '納期', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', '年末リリース', '12/28 公開は厳しいですか？先方は年始キャンペーンに使いたいそうです。', '12/28 は品質的に厳しいです。1/6 公開なら安全に出せます。先方への言い方も添えます。デプロイ判断はこちらに任せてください。', '12/28 はひんしつてきにきびしいです。1/6 こうかいならあんぜんにだせます。せんぽうへのいいかたもそえます。でぷろいはんだんはこちらにまかせてください。', '[{"text":"12/28 は品質的に厳しいです。","kana":"12/28 はひんしつてきにきびしいです。"},{"text":"1/6 公開なら安全に出せます。","kana":"1/6 こうかいならあんぜんにだせます。"},{"text":"先方への言い方も添えます。","kana":"せんぽうへのいいかたもそえます。"},{"text":"デプロイ判断はこちらに任せてください。","kana":"でぷろいはんだんはこちらにまかせてください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a26', 'advanced', '追加料金', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', '急な言語追加', '公開前日に中国語も、と言われました。やるなら追加料金で説明したいです。', '公開前日の追加は難しいです。この部分だけ追加対応になります。金額とリスクを短く書きます。本番の機嫌は今日は良さそうです。', 'こうかいぜんじつのついかはむずかしいです。このぶぶんだけついかたいおうになります。きんがくとりすくをみじかくかきます。ほんばんのきげんはきょうはよさそうです。', '[{"text":"公開前日の追加は難しいです。","kana":"こうかいぜんじつのついかはむずかしいです。"},{"text":"この部分だけ追加対応になります。","kana":"このぶぶんだけついかたいおうになります。"},{"text":"金額とリスクを短く書きます。","kana":"きんがくとりすくをみじかくかきます。"},{"text":"本番の機嫌は今日は良さそうです。","kana":"ほんばんのきげんはきょうはよさそうです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a27', 'advanced', 'accessibility', 'WebApp部', '加藤 / デザイナー', '/assets/avatars/kato.svg', '監査前修正', '`aria-label` 抜けとコントラスト、まとめて直してもらえますか？監査が来週です。', '`aria-label` とコントラストを先に直します。監査前にチェックリストも添付します。ログを見る前からだいたい勝ち筋は見えています。', '`aria-label` とこんとらすとをさきになおします。かんさまえにちぇっくりすともてんぷします。ろぐをみるまえからだいたいかちすじはみえています。', '[{"text":"`aria-label` とコントラストを先に直します。","kana":"`aria-label` とこんとらすとをさきになおします。"},{"text":"監査前にチェックリストも添付します。","kana":"かんさまえにちぇっくりすともてんぷします。"},{"text":"ログを見る前からだいたい勝ち筋は見えています。","kana":"ろぐをみるまえからだいたいかちすじはみえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a28', 'advanced', 'test', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', 'E2E不足', '決済の E2E が無くて不安です。最低限どれを足しますか？', '成功、失敗、二重送信の 3 本を足します。今夜 develop に出して、明日レビューお願いします。フィードバックより先に直しておきました。', 'せいこう、しっぱい、にじゅうそうしんの 3 ほんをたします。こんや develop にだして、あしたれびゅーおねがいします。ふぃーどばっくよりさきになおしておきました。', '[{"text":"成功、失敗、二重送信の 3 本を足します。","kana":"せいこう、しっぱい、にじゅうそうしんの 3 ほんをたします。"},{"text":"今夜 develop に出して、明日レビューお願いします。","kana":"こんや develop にだして、あしたれびゅーおねがいします。"},{"text":"フィードバックより先に直しておきました。","kana":"ふぃーどばっくよりさきになおしておきました。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a29', 'advanced', '404', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'リダイレクト漏れ', '旧 URL が 404 のままです。SEO 担当が焦っています。一覧はシートにあります。', 'シートの旧 URL を 301 で新 URL へ向けます。残件があれば別Issueに分けます。この程度ならリリース前のおやつです。', 'しーとのきゅう URL を 301 でしん URL へむけます。ざんけんがあればべつIssueにわけます。このていどならりりーすまえのおやつです。', '[{"text":"シートの旧 URL を 301 で新 URL へ向けます。","kana":"しーとのきゅう URL を 301 でしん URL へむけます。"},{"text":"残件があれば別Issueに分けます。","kana":"ざんけんがあればべつIssueにわけます。"},{"text":"この程度ならリリース前のおやつです。","kana":"このていどならりりーすまえのおやつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a30', 'advanced', 'cache', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'パージ手順', 'キャッシュクリアの手順、運用に渡せる形で残してください。本番事故防止です。', '手順を `1. 確認 2. パージ 3. 再読込` で残します。間違えて全消ししない注意も書きます。スコープが増えてもこちらのペースは変わりません。', 'てじゅんを `1. かくにん 2. ぱーじ 3. さいよみこみ` でのこします。まちがえてぜんけししないちゅういもかきます。すこーぷがふえてもこちらのぺーすはかわりません。', '[{"text":"手順を","kana":"てじゅんを"},{"text":" `1. 確認 2. パージ 3. 再読込` で残します。","kana":" `1. かくにん 2. ぱーじ 3. さいよみこみ` でのこします。"},{"text":"間違えて全消ししない注意も書きます。","kana":"まちがえてぜんけししないちゅういもかきます。"},{"text":"スコープが増えてもこちらのペースは変わりません。","kana":"すこーぷがふえてもこちらのぺーすはかわりません。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a31', 'advanced', 'performance', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', 'N+1', '商品詳細が遅いです。クエリログを添付しました。インデックスは既にあります。', '添付ログを見ると N+1 です。まとめ取得に変えて、ステージングで計測してから出します。障害にもこちらのスケジュールに合わせてもらいます。', 'てんぷろぐをみると N+1 です。まとめしゅとくにかえて、すてーじんぐでけいそくしてからだします。しょうがいにもこちらのすけじゅーるにあわせてもらいます。', '[{"text":"添付ログを見ると N+1 です。","kana":"てんぷろぐをみると N+1 です。"},{"text":"まとめ取得に変えて、ステージングで計測してから出します。","kana":"まとめしゅとくにかえて、すてーじんぐでけいそくしてからだします。"},{"text":"障害にもこちらのスケジュールに合わせてもらいます。","kana":"しょうがいにもこちらのすけじゅーるにあわせてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a32', 'advanced', 'browser', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', 'Safari崩れ', 'Safari だけ日付ピッカーが崩れます。Chrome は問題ありません。来週キャンペーンです。', 'Safari だけ再現します。ネイティブピッカーを避けて、同じ見た目に揃えます。キャンペーン前に出します。フルスタックなので切り分けは一筆です。', 'Safari だけさいげんします。ねいてぃぶぴっかーをさけて、おなじみためにそろえます。きゃんぺーんまえにだします。ふるすたっくなのできりわけはいっぴつです。', '[{"text":"Safari だけ再現します。","kana":"Safari だけさいげんします。"},{"text":"ネイティブピッカーを避けて、同じ見た目に揃えます。","kana":"ねいてぃぶぴっかーをさけて、おなじみためにそろえます。"},{"text":"キャンペーン前に出します。","kana":"きゃんぺーんまえにだします。"},{"text":"フルスタックなので切り分けは一筆です。","kana":"ふるすたっくなのできりわけはいっぴつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a33', 'advanced', '保守', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', '月次点検', '月次点検の報告、経営向けに 5 行でください。障害は無かった想定です。', '障害なし、更新 3 件、バックアップ確認済み、で 5 行にまとめます。数字は管理画面から拾います。コミット一つで空気が変わります。', 'しょうがいなし、こうしん 3 けん、ばっくあっぷかくにんずみ、で 5 ぎょうにまとめます。すうじはかんりがめんからひろいます。こみっとひとつでくうきがかわります。', '[{"text":"障害なし、更新 3 件、バックアップ確認済み、で 5 行にまとめます。","kana":"しょうがいなし、こうしん 3 けん、ばっくあっぷかくにんずみ、で 5 ぎょうにまとめます。"},{"text":"数字は管理画面から拾います。","kana":"すうじはかんりがめんからひろいます。"},{"text":"コミット一つで空気が変わります。","kana":"こみっとひとつでくうきがかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a34', 'advanced', '打合せ', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', '施策会議', '来週の施策会議で、AB テスト結果を説明してください。資料は簡易でよいです。', '勝った案と理由を 1 枚にします。数字は管理画面の期間指定と揃えておきます。デプロイ判断はこちらに任せてください。', 'かったあんとりゆうを 1 まいにします。すうじはかんりがめんのきかんしていとそろえておきます。でぷろいはんだんはこちらにまかせてください。', '[{"text":"勝った案と理由を","kana":"かったあんとりゆうを"},{"text":" 1 枚にします。","kana":" 1 まいにします。"},{"text":"数字は管理画面の期間指定と揃えておきます。","kana":"すうじはかんりがめんのきかんしていとそろえておきます。"},{"text":"デプロイ判断はこちらに任せてください。","kana":"でぷろいはんだんはこちらにまかせてください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a35', 'advanced', 'スケジュール', 'WebApp部', '中村 / PM', '/assets/avatars/nakamura.svg', 'マイルストーン', 'マイルストーンを `M1 / M2 / M3` で引き直してください。先方が来週確認します。', '`M1 / M2 / M3` で引き直します。先方確認用に前提と残リスクも 3 行添えます。本番の機嫌は今日は良さそうです。', '`M1 / M2 / M3` でひきなおします。せんぽうかくにんようにぜんていとざんりすくも 3 ぎょうそえます。ほんばんのきげんはきょうはよさそうです。', '[{"text":"`M1 / M2 / M3` で引き直します。","kana":"`M1 / M2 / M3` でひきなおします。"},{"text":"先方確認用に前提と残リスクも 3 行添えます。","kana":"せんぽうかくにんようにぜんていとざんりすくも 3 ぎょうそえます。"},{"text":"本番の機嫌は今日は良さそうです。","kana":"ほんばんのきげんはきょうはよさそうです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a36', 'advanced', 'API', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', 'レートリミット', '外部 API が 429 を返すようになりました。リトライ方針を決めて実装してください。', '429 は待ってから最大 3 回リトライします。それでもダメなら 500 にせず、後で再実行します。ログを見る前からだいたい勝ち筋は見えています。', '429 はまってからさいだい 3 かいりとらいします。それでもだめなら 500 にせず、あとでさいじっこうします。ろぐをみるまえからだいたいかちすじはみえています。', '[{"text":"429 は待ってから最大 3 回リトライします。","kana":"429 はまってからさいだい 3 かいりとらいします。"},{"text":"それでもダメなら 500 にせず、後で再実行します。","kana":"それでもだめなら 500 にせず、あとでさいじっこうします。"},{"text":"ログを見る前からだいたい勝ち筋は見えています。","kana":"ろぐをみるまえからだいたいかちすじはみえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a37', 'advanced', 'ログイン', 'Orion inc.', '鈴木 / 事業部', '/assets/avatars/suzuki.svg', 'セッション切れ', '操作中に突然ログイン画面へ戻されます。顧客説明用の一文もください。', '一定時間操作がないと安全のため切れます。再ログインすれば続きから戻れます、と案内できます。フィードバックより先に直しておきました。', 'いっていじかんそうさがないとあんぜんのためきれます。さいろぐいんすればつづきからもどれます、とあんないできます。ふぃーどばっくよりさきになおしておきました。', '[{"text":"一定時間操作がないと安全のため切れます。","kana":"いっていじかんそうさがないとあんぜんのためきれます。"},{"text":"再ログインすれば続きから戻れます、と案内できます。","kana":"さいろぐいんすればつづきからもどれます、とあんないできます。"},{"text":"フィードバックより先に直しておきました。","kana":"ふぃーどばっくよりさきになおしておきました。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a38', 'advanced', '進捗', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', '大型改修', '先方に今週の進捗を送りたいです。できたこと / 残 / リスクの 3 点でください。', 'できたこと、残作業、リスクの 3 点で送ります。リスクはリリース週の仕様追加だけです。この程度ならリリース前のおやつです。', 'できたこと、ざんさぎょう、りすくの 3 てんでおくります。りすくはりりーすしゅうのしようついかだけです。このていどならりりーすまえのおやつです。', '[{"text":"できたこと、残作業、リスクの 3 点で送ります。","kana":"できたこと、ざんさぎょう、りすくの 3 てんでおくります。"},{"text":"リスクはリリース週の仕様追加だけです。","kana":"りすくはりりーすしゅうのしようついかだけです。"},{"text":"この程度ならリリース前のおやつです。","kana":"このていどならりりーすまえのおやつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a39', 'advanced', '障害', '森カフェ', '森 / 店主', '/assets/avatars/mori.svg', '予約ステータス', '予約が全部「仮」のままです。店が午後の準備に入れません。今から見てもらえますか？', '仮のまま固まる不具合です。今から直して、確定に戻します。戻し完了後にご連絡します。この障害、既視感があります。勝てます。', 'かりのままかたまるふぐあいです。いまからなおして、かくていにもどします。もどしかんりょうごにごれんらくします。このしょうがい、きしかんがあります。かてます。', '[{"text":"仮のまま固まる不具合です。","kana":"かりのままかたまるふぐあいです。"},{"text":"今から直して、確定に戻します。","kana":"いまからなおして、かくていにもどします。"},{"text":"戻し完了後にご連絡します。","kana":"もどしかんりょうごにごれんらくします。"},{"text":"この障害、既視感があります。勝てます。","kana":"このしょうがい、きしかんがあります。かてます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a40', 'advanced', 'アクセス解析', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', '広告計測', '広告の CV が管理画面と合わず、出稿を止めるか判断したいです。今日中に切り分けできますか？', '広告側とサイト側の計測を一度切り分けます。ずれている期間が分かれば先に共有ください。今日中に結論を出します。障害にもこちらのスケジュールに合わせてもらいます。', 'こうこくがわとさいとがわのけいそくをいちどきりわけます。ずれているきかんがわかればさきにきょうゆうください。きょうじゅうにけつろんをだします。しょうがいにもこちらのすけじゅーるにあわせてもらいます。', '[{"text":"広告側とサイト側の計測を一度切り分けます。","kana":"こうこくがわとさいとがわのけいそくをいちどきりわけます。"},{"text":"ずれている期間が分かれば先に共有ください。","kana":"ずれているきかんがわかればさきにきょうゆうください。"},{"text":"今日中に結論を出します。","kana":"きょうじゅうにけつろんをだします。"},{"text":"障害にもこちらのスケジュールに合わせてもらいます。","kana":"しょうがいにもこちらのすけじゅーるにあわせてもらいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b33', 'beginner', '進捗', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', '週次同期', '今日のアサイン、どこまで進んでる？', 'キャッチアップして共有します。午後にはステータスを更新します。まだキャッチアップ中なので、先に共有します。', 'きゃっちあっぷしてきょうゆうします。ごごにはすてーたすをこうしんします。まだきゃっちあっぷちゅうなので、さきにきょうゆうします。', '[{"text":"キャッチアップして共有します。","kana":"きゃっちあっぷしてきょうゆうします。"},{"text":"午後にはステータスを更新します。","kana":"ごごにはすてーたすをこうしんします。"},{"text":"まだキャッチアップ中なので、先に共有します。","kana":"まだきゃっちあっぷちゅうなので、さきにきょうゆうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b34', 'beginner', 'test', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', 'QA確認', 'ログインのテスト項目、最低限どれを見ればよい？', '成功と失敗の2つを先に見ます。結果はレビュー用に残します。リスクは小さめだと思います。', 'せいこうとしっぱいの2つをさきにみます。けっかはれびゅーようにのこします。りすくはちいさめだとおもいます。', '[{"text":"成功と失敗の2つを先に見ます。","kana":"せいこうとしっぱいの2つをさきにみます。"},{"text":"結果はレビュー用に残します。","kana":"けっかはれびゅーようにのこします。"},{"text":"リスクは小さめだと思います。","kana":"りすくはちいさめだとおもいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b35', 'beginner', 'デザイン', 'WebApp部', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'ボタン色', 'エラーボタン、赤のままでよい？', '赤のまま進めます。フィードバックあれば直します。エラーとは今日が初対面ということにしておきます。', 'あかのまますすめます。ふぃーどばっくあればなおします。えらーとはきょうがしょたいめんということにしておきます。', '[{"text":"赤のまま進めます。","kana":"あかのまますすめます。"},{"text":"フィードバックあれば直します。","kana":"ふぃーどばっくあればなおします。"},{"text":"エラーとは今日が初対面ということにしておきます。","kana":"えらーとはきょうがしょたいめんということにしておきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b36', 'beginner', '打合せ', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', '営業同席', '明日10時の打合せ、開発からも1人出られる？', '出られます。先にスコープだけ整理します。レビュー待ちにしておきます。', 'でられます。さきにすこーぷだけせいりします。れびゅーまちにしておきます。', '[{"text":"出られます。","kana":"でられます。"},{"text":"先にスコープだけ整理します。","kana":"さきにすこーぷだけせいりします。"},{"text":"レビュー待ちにしておきます。","kana":"れびゅーまちにしておきます。"}]');
