INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('b38', 'beginner', 'API', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '一覧API', '一覧 API、空配列を返す仕様でよい？', 'その仕様で進めます。ドキュメントも更新します。コミット前にもう一度見ます。', 'そのしようですすめます。どきゅめんともこうしんします。こみっとまえにもういちどみます。', '[{"text":"その仕様で進めます。","kana":"そのしようですすめます。"},{"text":"ドキュメントも更新します。","kana":"どきゅめんともこうしんします。"},{"text":"コミット前にもう一度見ます。","kana":"こみっとまえにもういちどみます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m41', 'intermediate', '進捗', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', 'リリース週', '今週の残、先方説明用に3点で欲しい。', '残作業、リスク、次のアサインの3点で送ります。数字は管理画面から拾います。スコープ調整はこちらの得意領域です。', 'ざんさぎょう、りすく、つぎのあさいんの3てんでおくります。すうじはかんりがめんからひろいます。すこーぷちょうせいはこちらのとくいりょういきです。', '[{"text":"残作業、リスク、次のアサインの3点で送ります。","kana":"ざんさぎょう、りすく、つぎのあさいんの3てんでおくります。"},{"text":"数字は管理画面から拾います。","kana":"すうじはかんりがめんからひろいます。"},{"text":"スコープ調整はこちらの得意領域です。","kana":"すこーぷちょうせいはこちらのとくいりょういきです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m42', 'intermediate', 'bug', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', '再現手順', 'Issue #61、再現手順が薄いです。足してもらえますか？', '再現手順を追記します。ステージングの URL も添えます。リスクは先に潰してから共有します。', 'さいげんてじゅんをついきします。すてーじんぐの URL もそえます。りすくはさきにつぶしてからきょうゆうします。', '[{"text":"再現手順を追記します。","kana":"さいげんてじゅんをついきします。"},{"text":"ステージングの URL も添えます。","kana":"すてーじんぐの URL もそえます。"},{"text":"リスクは先に潰してから共有します。","kana":"りすくはさきにつぶしてからきょうゆうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m43', 'intermediate', 'UI', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', 'フロント差分', 'develop のカード崩れ、フロント側で見てくれる？', 'こちらで再現します。直したら PR 出します。デプロイまでセットで片します。', 'こちらでさいげんします。なおしたら PR だします。でぷろいまでせっとでかたします。', '[{"text":"こちらで再現します。","kana":"こちらでさいげんします。"},{"text":"直したら PR 出します。","kana":"なおしたら PR だします。"},{"text":"デプロイまでセットで片します。","kana":"でぷろいまでせっとでかたします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m44', 'intermediate', 'DB', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '遅いクエリ', '管理画面の検索、また10秒かかってます。', 'クエリを一度切り分けます。インデックスで足りなければ共有します。コミットメッセージも今日は冴えています。', 'くえりをいちどきりわけます。いんでっくすでたりなければきょうゆうします。こみっとめっせーじもきょうはさえています。', '[{"text":"クエリを一度切り分けます。","kana":"くえりをいちどきりわけます。"},{"text":"インデックスで足りなければ共有します。","kana":"いんでっくすでたりなければきょうゆうします。"},{"text":"コミットメッセージも今日は冴えています。","kana":"こみっとめっせーじもきょうはさえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m45', 'intermediate', 'deploy', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', '本番反映', '今夜のデプロイ、インフラ側の確認は済んでる？', '確認済みです。問題なければそのまま出します。ログが素直ならこちらの勝ちです。', 'かくにんずみです。もんだいなければそのままだします。ろぐがすなおならこちらのかちです。', '[{"text":"確認済みです。","kana":"かくにんずみです。"},{"text":"問題なければそのまま出します。","kana":"もんだいなければそのままだします。"},{"text":"ログが素直ならこちらの勝ちです。","kana":"ろぐがすなおならこちらのかちです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m46', 'intermediate', '見積もり', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', '追加見積', '先方が項目追加を言ってます。ざっくり金額ほしい。', '先に見積もりを出します。この部分だけ追加対応になります。キャッチアップ済みなので先に進めます。', 'さきにみつもりをだします。このぶぶんだけついかたいおうになります。きゃっちあっぷずみなのでさきにすすめます。', '[{"text":"先に見積もりを出します。","kana":"さきにみつもりをだします。"},{"text":"この部分だけ追加対応になります。","kana":"このぶぶんだけついかたいおうになります。"},{"text":"キャッチアップ済みなので先に進めます。","kana":"きゃっちあっぷずみなのでさきにすすめます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a41', 'advanced', '緊急', 'WebApp部', '佐々木 / 上長', '/assets/avatars/sasaki.svg', '金曜障害', '本番500が続いてます。先方説明用の一文もください。', '注文 API から切り分けます。復旧でき次第、短い説明文も送ります。フルスタックなので切り分けは一筆です。', 'ちゅうもん API からきりわけます。ふっきゅうできしだい、みじかいせつめいぶんもおくります。ふるすたっくなのできりわけはいっぴつです。', '[{"text":"注文","kana":"ちゅうもん"},{"text":" API から切り分けます。","kana":" API からきりわけます。"},{"text":"復旧でき次第、短い説明文も送ります。","kana":"ふっきゅうできしだい、みじかいせつめいぶんもおくります。"},{"text":"フルスタックなので切り分けは一筆です。","kana":"ふるすたっくなのできりわけはいっぴつです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a42', 'advanced', 'test', 'WebApp部', '青木 / QA', '/assets/avatars/aoki.svg', 'E2E不足', '決済の E2E、成功失敗と二重送信だけでも今夜欲しいです。', '3本を今夜 develop に出します。レビューは明日回してください。コミット一つで空気が変わります。', '3ほんをこんや develop にだします。れびゅーはあしたまわしてください。こみっとひとつでくうきがかわります。', '[{"text":"3本を今夜 develop に出します。","kana":"3ほんをこんや develop にだします。"},{"text":"レビューは明日回してください。","kana":"れびゅーはあしたまわしてください。"},{"text":"コミット一つで空気が変わります。","kana":"こみっとひとつでくうきがかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a43', 'advanced', 'PR', 'WebApp部', '伊藤 / フロントエンド', '/assets/avatars/ito.svg', 'レビュー lag', 'PR #201、フロント差分だけ先に見てもらえますか？', '今日見ます。指摘が少なければ午後までにマージします。デプロイ判断はこちらに任せてください。', 'きょうみます。してきがすくなければごごまでにまーじします。でぷろいはんだんはこちらにまかせてください。', '[{"text":"今日見ます。","kana":"きょうみます。"},{"text":"指摘が少なければ午後までにマージします。","kana":"してきがすくなければごごまでにまーじします。"},{"text":"デプロイ判断はこちらに任せてください。","kana":"でぷろいはんだんはこちらにまかせてください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a44', 'advanced', 'SQL', 'WebApp部', '田中 / バックエンド', '/assets/avatars/tanaka.svg', '集計会議', '売上集計が CSV と違います。明日10時の会議に間に合う？', 'SQL と CSV の条件を突き合わせます。明日の午前中に共有します。本番の機嫌は今日は良さそうです。', 'SQL と CSV のじょうけんをつきあわせます。あしたのごぜんちゅうにきょうゆうします。ほんばんのきげんはきょうはよさそうです。', '[{"text":"SQL と CSV の条件を突き合わせます。","kana":"SQL と CSV のじょうけんをつきあわせます。"},{"text":"明日の午前中に共有します。","kana":"あしたのごぜんちゅうにきょうゆうします。"},{"text":"本番の機嫌は今日は良さそうです。","kana":"ほんばんのきげんはきょうはよさそうです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a45', 'advanced', 'staging', 'WebApp部', '藤田 / インフラ', '/assets/avatars/fujita.svg', '権限リリース', 'ロール変更ありです。本番へ出してよいですか？', '念のためバックアップを取ってから作業します。管理者ログインだけ先に確認します。ログを見る前からだいたい勝ち筋は見えています。', 'ねんのためばっくあっぷをとってからさぎょうします。かんりしゃろぐいんだけさきにかくにんします。ろぐをみるまえからだいたいかちすじはみえています。', '[{"text":"念のためバックアップを取ってから作業します。","kana":"ねんのためばっくあっぷをとってからさぎょうします。"},{"text":"管理者ログインだけ先に確認します。","kana":"かんりしゃろぐいんだけさきにかくにんします。"},{"text":"ログを見る前からだいたい勝ち筋は見えています。","kana":"ろぐをみるまえからだいたいかちすじはみえています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a46', 'advanced', '顧客説明', '営業部', '渡辺 / 営業', '/assets/avatars/watanabe.svg', '遅延説明', '在庫ずれの理由、先方に技術用語少なめでください。', '更新が数分まとめて入るためです。即時反映に変えて、完了後に共有します。フィードバックより先に直しておきました。', 'こうしんがすうふんまとめてはいるためです。そくじはんえいにかえて、かんりょうごにきょうゆうします。ふぃーどばっくよりさきになおしておきました。', '[{"text":"更新が数分まとめて入るためです。","kana":"こうしんがすうふんまとめてはいるためです。"},{"text":"即時反映に変えて、完了後に共有します。","kana":"そくじはんえいにかえて、かんりょうごにきょうゆうします。"},{"text":"フィードバックより先に直しておきました。","kana":"ふぃーどばっくよりさきになおしておきました。"}]');
